const metricsAggregator = require("../lib/GcMetricsAggregator");
const constants = require("./constants"); // No I18N

describe("GC aggregator for individual metric type", () => {
  var gcMetricsAggs = new metricsAggregator();

  beforeEach(() => {
    gcMetricsAggs = new metricsAggregator();
    //aggregating stats
    gcMetricsAggs.addToExistingMetricData(constants.GC_STATS[0]);
    gcMetricsAggs.addToExistingMetricData(constants.GC_STATS[3]);
  }, 1);

  //Testing member method types
  test("defines addToExistingMetricData()", () => {
    expect(typeof gcMetricsAggs.addToExistingMetricData).toBe("function");
  });

  //Testing return types of each method
  test("addToExistingMetricData() returns undefined when called", () => {
    expect(
      gcMetricsAggs.addToExistingMetricData(constants.GC_STATS[0])
    ).toBeUndefined();
  });

  //Aggregation logic test
  test("addToExistingMetricData logic", () => {
    expect(gcMetricsAggs.max).toBe(constants.GC_STATS_AGGREGATED_VALUE[0].max);
    expect(gcMetricsAggs.min).toBe(constants.GC_STATS_AGGREGATED_VALUE[0].min);
    expect(gcMetricsAggs.sum).toBe(constants.GC_STATS_AGGREGATED_VALUE[0].sum);
    expect(gcMetricsAggs.count).toBe(
      constants.GC_STATS_AGGREGATED_VALUE[0].count
    );
  });
});
